## User-defined Class for Blog News Custom Post Type

Here's an example implementation of the Blog News Custom Post Type class:

```php
<?php

namespace BlogNews;

use DateTime;
use PostType;
use WP_Query;
use WP_Widget;

/**
 * A class to register and manage the Blog News Custom Post Type.
 */
class CustomPostType extends PostType {

    /** @var string The slug to use for the custom post type. */
    protected $slug;

    /**
     * Constructor to set the slug.
     * @param string $slug The slug for the custom post type.
     */
    public function __construct( string $slug ) {
        $this->slug = $slug;
        parent::__construct(
            [
                'public' => true,
                'label'  => __( 'Blog News' ),
                'menu_icon' => 'dashicons-edit',
                'supports' => [
                    'title',
                    'editor',
                    'author',
                    'revisions'
                ],
                'show_in_rest' => true,
                'rest_base' => $this->slug,
                'rest_controller_class' => 'WP_REST_Posts_Controller'
            ]
        );
    }

    /**
     * Registers the custom post type.
     * @return void
     */
    public function register() : void {
        register_post_type( $this->name, $this->args );
    }

    /**
     * Creates a new instance of the custom post type.
     * @param array $args Arguments to pass to the post type constructor.
     * @return CustomPostType
     */
    public static function create( array $args = [] ) : CustomPostType {
        $instance = new static( $args['slug'] ?? 'blog_news' );
        if ( empty( $args ) ) {
            $instance->register();
        } elseif ( isset( $args['register'] ) && $args['register'] ) {
            $instance->register();
        }
        return $instance;
    }

    /**
     * Retrieve posts of the custom post type.
     * @param array $args Arguments to pass to WP_Query.
     * @return WP_Post[]
     */
    public function get_posts( array $args = [] ) : array {
        $defaults = [
            'post_type' => $this->name,
            'posts_per_page' => -1,
            'orderby' => 'date',
            'order' => 'DESC'
        ];
        $query_args = wp_parse_args( $args, $defaults );
        return (array) WP_Query( $query_args )->posts;
    }

    /**
     * Get a post object of the custom post type by ID.
     * @param int $post_id The ID of the post.
     * @return WP_Post|null
     */
    public function get_post( int $post_id ) : ?WP_Post {
        return get_post( $post_id, OBJECT );
    }

    /**
     * Create or get a term with the given slug.
     * @param string $slug The slug for the term.
     * @param string $taxonomy The taxonomy to register the term in.
     * @return Term
     */
    public function get_term( string $slug, string $taxonomy ) : Term {
        $terms = get_terms( [
            'taxonomy' => $taxonomy,
            'slug' => $slug,
            'hide_empty' => false
        ] );
        $term = reset( $terms ) ?? new Term( [
            'slug' => $slug,
            'name' => __( "Category '$slug'" ),
            'parent' => 0,
            'description' => '',
            'taxonomy' => $taxonomy
        ] );
        return $term;
    }

    /**
     * Update the post data and save it.
     * @param int $post_id The WP_Post ID to update.
     * @param array $data The post data to update.
     * @return bool True on success, false otherwise.
     */
    public function update_post( int $post_id, array $data ) : bool {
        $post = get_post( $post_id );
        if ( empty( $post ) || $post->post_type !== $this->name ) {
            return false;
        }
        $update = [];
        foreach ( $data as $field => $value ) {
            if ( has_filter( "editable_field_{$this->name}_$field" ) ) {
                $update[ $field ] = apply_filters( "editable_field_{$this->name}_$field", $value, $post );
            } else {
                $update[ $field ] = $value;
            }
        }
        $old_post = clone $post;
        foreach ( $update as $field => $value ) {
            switch ( $field ) {
                case 'title':
                    $post->post_title = $value;
                    break;
                case 'content':
                    $post->post_content = $value;
                    break;
                case 'categories':
                    wp_set_object_terms( $post_id, array_map( [ $this, 'get_term' ], (array) $value ), 'category', false );
                    break;
                case 'meta':
                    $meta = (array) $value;
                    foreach ( $meta as $field => $value ) {
                        delete_post_meta( $post_id, $field );
                        add_post_meta( $post_id, $field, $value, true );
                    }
                    break;
                default:
                    $post->$field = $value;
                    break;
            }
        }
        wp_update_post( $post );
        return $old_post->ID === $post->ID;
    }

}

/**
 * A class to register and manage Terms in the Blog News custom post type taxonomy.
 */
class Term extends \WP_Term {

    /**
     * Creates a new Term instance.
     *
     * @param array $args Arguments for the WP_Term constructor.
     */
    public function __construct( array $args ) {
        parent::__construct( $args );
        add_action( "edited_{$this->taxonomy}", [ $this, 'save' ] );
        add_action( "created_{$this->taxonomy}", [ $this, 'save' ] );
    }

    /**
     * Saves the term.
     *
     * @param int $term_id ID of the term.
     */
    public function save( int $term_id ) : void {
        $name = sanitize_title( stripslashes( $_POST['name'] ) );
        $slug = sanitize_title( $name );
        $description = $_POST['description'];
        wp_update_term( $term_id, $this->taxonomy, [
            'name' => $name,
            'slug' => $slug,
            'description' => $description
        ] );
    }

}
```

