    firewood_regex = /\d+ firewood/

    if food_regex.match?(statement.downcase)
      match = statement.downcase.match?(food_regex)
      food = match[1].to_i
    end

    if water_regex.match?(statement.downcase) && firewood_regex.match?(statement.downcase)
