double energy = (6.62607004 * Math.Pow(10,-34) * speedOfLight) / wavelength; // Вычисление энергии фотона, используя формулу E = h*c/λ
double h = energy / (speedOfLight * wavelength); // Вычисление постоянной Планка с учетом длины волны и скорости света

// Вывод результатов расчетов
Console.WriteLine("Значение постоянной Планка (h) равно: {0} Дж·с", h.ToString("F15")); // Пример вывода: "Значение постоянной Планка (h) равно: 4,1367584118021778×10^-34 Дж·с"
