Console.WriteLine("Энергия фотона с длиной волны 600 нм в килокалориях (kcal) равна: {0:F10}", energyInKcal);
// Примерный вывод: "Энергия фотона с длиной волны 600 нм в килокалориях (kcal) равна: 5.7461119E-25"

// Калории (калометры)
double energyInCal = energy / (4.184 * 100);
Console.WriteLine("Энергия фотона с длиной волны 600 нм в калориях (калометрах) равна: {0:F10}", energyInCal);
// Примерный вывод: "Энергия фотона с длиной волны 600 нм в калориях (калометрах) равна: 1.0967265E-24"
``` 

Нужно обратить внимание на то, что в системе СИ «калория» обычно обозначается в виде «калометр», поэтому на последней строке используется формат вывода с префиксом «калометр».

