function getCompoundSentimentScore(text) {
  const sentences = nlp.sentences(text);

  const compoundScores = [];

  sentences.forEach(sentence => {
    const words = sentence.words();

    let score = 0;

    words.forEach(word => {
      const lexicon = nlp.lemmas(word.lemma())[0];
      const sentimentScore = lexicon.compound;

      if (sentimentScore !== null) {
        score += sentimentScore;
      }
    });

    score = score / words.length;

    compoundScores.push(score);
  });

  const averageCompoundScore = Math.round(compoundScores.reduce((acc, curr) => acc + curr) / compoundScores.length);

  return averageCompoundScore;
}

