   ```java
   import java.util.Optional;
   import javax.persistence.EntityManager;
   import javax.persistence.PersistenceContext;

   public interface InvoiceRepository {
       Optional<InvoiceEntity> findById(Long id);

       InvoiceEntity save(InvoiceEntity invoiceEntity);
   }

   import javax.persistence.EntityManagerFactory;
   import javax.persistence.Persistence;

   public class JpaInvoiceRepository implements InvoiceRepository {
       @PersistenceContext
       private EntityManager entityManager;

       public JpaInvoiceRepository(EntityManagerFactory entityManagerFactory) {
           entityManager = entityManagerFactory.createEntityManager();
       }

       @Override
       public Optional<InvoiceEntity> findById(Long id) {
           return Optional.ofNullable(entityManager.find(InvoiceEntity.class, id));
       }

       @Override
       public InvoiceEntity save(InvoiceEntity invoiceEntity) {
           entityManager.persist(invoiceEntity);
           return invoiceEntity;
       }
   }
   ```

