    )

  // 2. Исследование разнообразия, учитывая поляризационные эффекты

  // Вычисляем метрики расхождения для каждого столбца
  val numCols = preprocessed.columns
  val statMatrix = Array.tabulate(numCols)(c =>
    // Вычисляем медиану в столбце и разность медианы со значениями столбца
    val col = preprocessed(columnIndex = c, _) // Получаем столбец в dataframe с индексом c
    col.map { x =>
      val median = col.median // Вычисляем медиану для столбца с индексом `c`
      abs(x - median) //Разница между значением и медианой столбца
    }.reduce(_ + _) // Сумма разностей для столбца с индексом `c`
  )

  // Получаем индексы столбцов с наибольшей разницей, на основе метрики разности медиан
  val relevantCols = statMatrix
    .zipWithIndex // Объединить матрицу статистики со своими индексами
    .sortBy(_._1) // Сортировка столбцов с наибольшей разницей по понижению значений
    .reverse // В обратном порядке
    .take(5) // Возвращаем толькоtop 5 столбцов
    .map(_._2) // Извлекаем индексы столбцов

  // Преобразуем оставшиеся столбцы в новый псевдо-столбец с глобальной средней
  val globalMean = preprocessed.cols.foldLeft(Double.PositiveInfinity) { (acc, col) =>
    col.reduceOption(_ + _) match {
      case Some(sum) => math.min(acc, sum / col.length.toDouble)
      case None => acc // либо NaN или missing, в таком случае сохраняем old min acc
    }
  }

  val dataWithRelevantCols = preprocessed.map {
    row =>
      val relevantRow = relevantCols.mapIndexed { (index, colIndex) =>
        row(colIndex) // Взять значение столбца с индексом colIndex из строки row
      }

      val othersRow = Array.fill(numCols - relevantCols.length)(globalMean) // Заполняем остальные столбцы смещенным значением

      relevantRow ++ othersRow // Слепляем новый столбец с выделенными признаками и псевдо-столбце Others
  }

  // 3. Анализ функциональностей на основе выделенных столбцов

  // Группируем на основе одинаковых значений в столбце бизнес-успешности, и запускаем k-медианные алгоритмы
  val result = KMeansAlgorithm()
