    .fit(dataWithRelevantCols) |> { algo =>
      // Получение результатов кластеризации
      val clusterResult = algo.getModel() // Возвращает модель k-Means
      val labelsDS = algo.transform(dataWithRelevantCols) // Преобразуем данные в набор меток кластеров

      // Получаем наименования столбцов, участвующих в построении модели
      val relevantColsNames = relevantCols.map(columnIndex => dataWithRelevantCols.apply(0)(columnIndex).toString)

      // Возвращаем множество кластеров и список пар столбцов и крайних значений
      (labelsDS, relevantColsNames.zipWithIndex.map {
        case (colName, colIndex) =>
