   Map<FlowerName, Set<String>> categories = new HashMap<>();

   for (String flower : flowers) {
       FlowerName key;
       for (FlowerName name : FlowerName.values()) {
           if (startsWith(flower, name.getStartingLetter())) {
               key = name;
               break;
           }
