```python
FLOWERS = ["Лилии", "Гвоздики", "Маргаритки", "Бархатцы", "Хризантемы"]

def categorize(flowers):
    categories = {
        "Сирень": [],
        "Маргаритка": [],
        "Бархатцы": [],
        "Хризантема": [],
    }

    for flower in flowers:
        key = flower[:-1].capitalize()  # убираем последнюю букву (на английском языке) и переводим в заглавные буквы

