import static net.egork.fast.io.*;
import static net.egork.rubiks_cube_solver.api.*;
import java.io.File;

public class Main {
    public static void main(String[] args) throws Exception {
        CubeSolver solver = new CubeSolver();

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.parse(new File("rubiks_cube.xml"));
        doc.getDocumentElement().normalize();

        CubeState cubeState = solver.loadCube(doc);

        List<String> steps = solver.solveCube(cubeState);

        System.out.printf("Solved cube steps: %s%n", String.join(" ", steps));
    }
}
```

