## Создание соединения с MongoDB и схемы прикладных данных

После установки, создайте новый файл `index.js` с следующим содержимым:

```javascript
// npm install mongoose
const mongoose = require('mongoose');

const URL = process.env.MONGODB_URL || 'mongodb://localhost/myapp';

mongoose.connect(URL, {
  useNewUrlParser: true,
  useUnifiedTopology: true,
})
  .then(() => {
    console.log('Соединение с MongoDB установлено');
  })
  .catch((error) => {
    console.error('Ошибка подключения к MongoDB:', error);
  });

const mySchema = new mongoose.Schema({
  name: String,
  age: Number,
});

const MyModel = mongoose.model('MyModel', mySchema);

async function createDocument() {
  const document = new MyModel({ name: 'John Doe', age: 30 });
  const result = await document.save();
  console.log(result);
}

async function retrieve Documents() {
  const docs = await MyModel.find();
  console.log(docs);
}

async function deleteDocument() {
  const result = await MyModel.deleteOne({ name: 'John Doe' });
  console.log(result);
}

async function updateDocument() {
  const filter = { name: 'John Doe' };
  const update = { age: 35 };
  const options = { upsert: true, new: true };

  const result = await MyModel.updateOne(filter, update, options);
  console.log(result);
}

// Поля функций приведены только как пример и подлежат адаптации в соответствии с потребностями вашего приложения

createDocument()
  .then(() => retrieveDocuments())
  .then(() => deleteDocument())
  .then(() => updateDocument())
  .catch((err) => console.error(err));
```

В примере использовалось изменение имени по-умолчанию экземпляра модели с `User` на `MyModel`. Вы можете присвоить любое имя для модели в соответствии с вашим приложением.

В коде также используется переменная окружения `MONGODB_URL` для указания и настройки URL и потенциальных дополнительных опций для подключения к MongoDB. Если неизвестно будут ли использоваться другие настройки, использовать можно значение по умолчанию `mongodb://localhost/myapp`.

