```

### Обработка разнообразных типов запросов

Создайте файл `server.js` в корневой директории проекта и добавьте наивный код:

```javascript
const express = require('express');
const bodyParser = require('body-parser');
const app = express();

// Обработка запросов с телом формата `application/x-www-form-urlencoded`
app.use(bodyParser.urlencoded({ extended: true }));

// Обработка запросов с телом формата `application/json`
app.use(express.json());

// Обработка GET-запросов на корневом роуте '/'
app.get('/', (req, res) => {
  res.status(200).send('¡¡Hola mundo!!');
});

// Обработка GET-запросов на роуте '/users/{id}'
app.get('/users/:id', (req, res) => {
  const { id } = req.params;

  res.status(200).json({ userId: parseInt(id, 10) });
});

// Обработка POST-запросов на роуте '/api/users'
app.post('/api/users', (req, res) => {
  const { username, email } = req.body;

  res.status(201).json({ userId: 1, username, email });
});

// Обработка PUT-запросов на роуте '/api/users/:id'
app.put('/api/users/:id', (req, res) => {
  const { id } = req.params;
  const { username, email } = req.body;

  res.status(204).send();
});

// Обработка DELETE-запросов на роуте '/api/users/:id'
app.delete('/api/users/:id', (req, res) => {
  const { id } = req.params;

  res.status(204).send();
});

// Рекурсивный стабильный роутер для определеннных типов URL
const router = express.Router();

router.get('/', (req, res) => {
  res.status(200).send('¡¡Hola mundo con rutas recursivas!!');
});

// /api/books/12345
router.get('/:id', (req, res) => {
  const { id } = req.params;

  res.status(200).json({ isbn: id });
});

app.use('/api/books', router);

// Включение приложения на определенном порту
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Сервер запущен на http://localhost:${PORT}`);
});
```

Всё что вы увидели выше представляет собой примеры маршрутизации в Express и эффективное использование middleware для настройки типов запросов JSON и URL-кодированных. Существуют другие настройки и методы маршрутизации, поэтому рекомендуется прочитать [официальную документацию Express](https://expressjs.com/guide/routing.html) и [официальную документацию на middleware Express](https://expressjs.com/guide/middleware.html) для получения более полной и подробной информации.

