```javascript
// Добавление маршрутизации

app.get('/', (req, res) => {
  res.render('home');
});

app.post('/send', (req, res) => {
  const { name, email, phone, message } = req.body;

  if (!name || !email || !message) {
    res.status(422).render('error', { message: '_all_fields_are_required' });
    return;
  }

  // Выполнение POST-запроса на API для отправки данных
  axios.post(process.env.API_URL, {
    name,
    email,
    phone: phone.replace(/[^\d]/g, ''),
    message,
  }, {
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${process.env.API_TOKEN}`,
    },
  })
    .then(response => {
      if (response.status !== 200) {
        res.status(500).render('error', { message: 'internal_server_error' });
        return;
      }

      res.redirect('/');
    })
    .catch(error => {
      const status = error.response ? error.response.status : 500;

      if (status === 422) {
        const { message } = error.response.data;

        res.status(422).render('error', { message });
        return;
      }

      res.status(500).render('error', { message: 'internal_server_error' });
    });
});

// Обработка ошибок

app.use((err, req, res, next) => {
  console.error(err.stack);

  res.status(500).render('error', { message: 'internal_server_error' });
});

// Слушаем указанный порт

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Сервер запущен на порту ${PORT}`));
```

