\section{Современные структуры данных с плавающей запятой}

\subsection{Пример 1: Двоичный поисковый дерево}

Двоичный поисковое дерево (БСТ) — это встроенная структура данных, которая поддерживает операции поиска, вставки и удаления элементов в лексикографическом порядке, используя эффективную алгоритмическую сложность в худшем случае $O(log~n)$. БСТ полезно при решении задач на основе отсортированных подсётров. 

\begin{algorithm}[H]% Габоритный блок для заключения алгоритма в презентацию
\SetKwInOut{Input}{Вход}
\SetKwInOut{Output}{Выход}

\Input{Закодированная последовательность целых чисел $(a_0, a_1, \dots, a_{n-1})$ в диапазоне $[0, m-1]$, максимальная длинная подпоследовательность $k$ и сейчас используемая подпоследовательность $(a_i, a_{i+1}, \dots, a_{i+k-1})$, начиная с индекса $i$}
\Output{Максимальную подпоследовательность неубывных чисел длины $k$ из $n$ чисел($(a_0, a_1, \dots, a_{n-1})$) или константу $(-1, -1)$, если такая последовательность не найдена}

\BlankLine

% Алгоритм Бинарного поискового дерева
\If{$i \geq n-k$} % Завершение поиска при нехватке чисел для формирования подпоследовательности
    \Return $(-1, -1)$
\Else
    $j \xleftarrow[]{\text{Бинарный поиск}} \argmax\limits_{j \in [i, i+k-1]} (j - i + 1) \cdot a_j$\% Алгоритм поисковый, применяющий Бинарный поиск для нахождения индекса последнего элемента подпоследовательности
    $left \xleftarrow[]{\text{Функция рекурсии}}$ ПроверитьСледующую$(i, j, k-1)$\% Рекурсивный вызов функции на левой подпоследовательности
    $right \xleftarrow[]{\text{Функция рекурсии}}$ ПроверитьПредыдущую$(j+1, i+k-1, k-1)$\% Рекурсивный вызов функции на правой подпоследовательности

    \If{$left \leq right$}
        \Return $(left, right)$
    \EndIf

    \Return $(-1, -1)$
\EndIf

\caption{Разложение на нетривиальные подпоследовательности неубывающих чисел с помощью БСТ}
\label{alg:BST}
\end{algorithm}

\subsection{Пример 2: Бинарное дерево поиска}

Бинарное дерево поиска (БДП) — это эффективная структура данных, которая поддерживает операции поиска, вставки и удаления элементов в лексикографическом порядке, сохраняя баланс дерева за счёт регулярной рекоррекции любой из ветвей, если они сильно отличаются по высоте. Как и БСТ, БДП использует алгоритмическую сложность в худшем случае $O(log~n)$ для большинства операций на небольшом количестве элементов.

\begin{algorithm}[h]
\SetKwInOut{Input}{Вход}
\SetKwInOut{Output}{Выход}

\Input{Некорректно отсортированная последовательность целых чисел $(a_0, a_1, \dots, a_{n-1})$, добавляемый элемент $x$}
\Output{Отсортированная последовательность $(a_0, a_1, \dots, a_{n-1}, x)$}

\BlankLine

% Алгоритм Бинарного дерева поиска
\If{$n = 0$}
    \Return $(x)$%\% Просто вставляем элемент в пустую структуру данных
\ElseIf{$x < a_0$}
    $left \xleftarrow[]{\text{Функция рекурсии}}$ Вставить$(x, a_1, \dots, a_{n-1})$ %Рекурсивный вызов на левой поддереве
    \Return $(x, a_0, left)$% По возвращении преобразование левой подструктуры в левую ветвь
\ElseIf{$x > a_{n-1}$}
    $right \xleftarrow[]{\text{Функция рекурсии}}$ Вставить$(a_0, \dots, a_{n-2}, x, n - 2)$% Рекурсивный вызов на правой поддереве
    \Return $(a_0, \dots, a_{n-2}, x, a_{n-1})$% По возвращении преобразование правой подструктуры в правую ветвь
\Else % $a_i \leq x < a_{i+1}$ для некоторого $i$, найденного бинарным поиском
    $left \xleftarrow[]{\text{Функция рекурсии}}$ Вставить$(x, a_{i+1}, \dots, a_{n-1})$% Рекурсивный вызов на левой поддереве (тут вставлен элемент не на последней позиции в поддереве)
    \Return $(a_0, \dots, a_i, left, a_{i+1}, \dots, a_{n-1})$% По возвращении преобразование левой подструктуры в левую ветвь, а правой подструктуры в правую ветвь
\EndIf

\caption{Вставка элемента в БДП}
\label{alg:BDP}
\end{algorithm}

