class IntQueue {
  private int[] data; // массив для хранения элементов
  private int front; // указатель на начало очереди
  private int back; // указатель на последнюю позицию в очереди

  IntQueue() {
    data = new int[10]; // инициализация с небольшой емкостью вектора (может быть расширенной динамически в ходе работы)
    front = 0; // начало очереди - это первая позиция вектора
    back = -1; // отсутствует элемент в последней позиции вектора
  }

  void enqueue(int element) {
    if (back >= data.length - 1) {
      // проверка переполнения вектора
      resize(2 * data.length);
    }
    back++; // следующая позиция для вставки добавленного элемента
    data[back] = element; // вставка элемента в последнюю позицию вектора
  }

  int dequeue() {
    if (isEmpty()) {
      throw new NoSuchElementException();
    }
    int element = data[front++]; // извлечение элемента с указателя на начало очереди
    if (front > back + 1 || (front == back + 1 && isEmpty())) {
      // сдвиг указателя на начало очереди на позицию вперед, если необходимо
      front = 0;
    }
    return element;
  }

  int seeSaw() {
    int sum = 0;

    // начиная с позиции front, происходит проход по последовательности вектора с подстановкой выражений
    // 1 / (элемент + переменная сумма) вновь в каждой итерации, начиная с позиции position.
    int position = front;
    while (position <= back) {
      int currentElement = data[position];
      int denominator = currentElement + sum;
      sum += 1 / denominator;
      position++;
    }

    return sum;
  }

  private boolean isEmpty() {
    return front > back;
  }

  private void resize(int capacity) {
    int[] temp = new int[capacity];
    for (int I = front; I <= back; i++) {
      temp[i - front] = data[i];
    }
    data = temp;
    front = 0;
    back = data.length - 1;
  }
}
```

Как видно, в этом варианте используются побочные эффекты динамических массивов, таких как изменение длины вектора и итерации по элементам вектора. Поэтому, хотя все операции, за исключением seeSaw(), выполняются в среднем за время O(1), в худшем случае вставка (resize) может займёт O(n), где n - текущая длина очереди.

