```rust
use std::collections::HashSet;
use std::error::Error;
use std::io::{self, Write};
use std::str::FromStr;

use regex::Regex;

use crate::core::{langdetect::Language, pos_tagger::POS_TAGGER};
use crate::util::wordnet::{self, Synset, Noun};

enum VerbType {
    ToBe,
    Main,
}

impl FromStr for VerbType {
    type Err = Box<dyn Error>;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "be" | "am" | "is" | "are" | "was" | "were" | "being" | "been" => Ok(VerbType::ToBe),
            _ => Ok(VerbType::Main),
        }
    }
}

fn main() {
    println!("Введите предложение, и программа определит объект: ");

    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");

    let sentence = input.trim();

    let language = Language::detect(&sentence).unwrap();
    let tags: Vec<_> = POS_TAGGER.parse_tags(&language, &sentence).unwrap();

    let (subject, verb, obj) = extract_subject_verb_object(&tags);

    match (verb, obj) {
        (Some((_, _, _)), Some((_, _, _))) => {
            let lemma = wordnet::lemmatize(&obj.0.to_lowercase()).unwrap();
            let synset = Synset::from_tree_id(wordnet::wordnet_lang_codes(&language)[0], lemma);
            let noun = synset.pos().to_noun().unwrap();

            println!("{}", noun.lemma().to_lowercase());
        }
        _ => println!("Нет объекта в предложении"),
    }
}

fn extract_subject_verb_object(mut tags: Vec<(String, String, String)>) -> (Option<(String, String, String)>, Option<(String, String, String)>, Option<(String, String, String)> ) {
    tags.reverse();

    let mut prev_tag = (String::new(), String::new(), String::new());
    let mut verb_type = None;

    for (word, pos, _) in tags.iter() {
        let (ptype, _, _) = prev_tag;
        let (mut nptype, _, _) = (*word, pos, String::new());

        match pos.chars().nth(0) {
            Some('V') => {
                // главный глагол в конце предложения
                nptype = VerbType::Main.to_string();

                if verb_type.is_none() {
                    // первый глагол в предложении
                    verb_type = Some(nptype.clone());
                } else if verb_type.as_ref().unwrap() == "ToBe" {
                    // глагол «быть» не является тем же, что и наш главный глагол
                    nptype = VerbType::Main.to_string();
                }

                break;
            }
            Some('N') | Some('P') => (),
            _ => continue,
        }

        prev_tag = (ptype, pos.clone(), nptype.clone());

        if pos.starts_with("NN") || pos.starts_with("NNP") || pos.starts_with("NNPS") || pos.starts_with("NNS") {
            // заменяем существительные на нижний регистр
            *nptype = nptype.to_lowercase();
        }

        if let Some((s, _, _)) = &verb_type {
            if nptype == *s {
                return (Some(prev_tag), Some((word.clone(), pos.clone(), nptype.clone())), None);
            }

            if nptype != "ToBe" && prev_tag.0.is_empty() {
                break;
            }
        }
    }

    let (mut subj, mut verb, mut obj) = (None, None, None);

    if verb_type.map_or(false, |t| t == "ToBe") {
