async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Получите путь к установленной модели spaCy
    let model_path = env::var("SPACY_MODEL_PATH")?;

    // Загрузите модель SpacyModel для анализа английского языка
    let nlp = spacy_langdetect::Spacy::new(model_path)?;

