    let doc: spacy::Document = nlp
        .nlp(sentence)
        .unwrap()
        .lang(lang.to_string())
        .to_document()?;

    // Находим совпадение с фигурными скобками в данном предложении
    let token_match = doc
        .tokens()
        .filter(|token| token.text().contains.Match(&[r#"{{[^}]+}}"#].iter().cloned()))
        .collect::<Vec<_>>();

