def lexicon_tagging(words, tag_set)
  pos_tags = words.map.with_index do |word, i|
    if (word == 'Сиракузах') || (word == 'Нью-Йорк') || (word == 'экологический')
      tag_set[word.to_sym]
    elsif word == 'новый'
      tag_set['ADJ']
    elsif word == 'маркетинговый'
      tag_set['ADJ']
    elsif word == 'подчеркивает'
      tag_set['VERB']
    elsif word == 'экологическую'
      tag_set['ADJ']
    else
      'O'
    end
  end
  pos_tags
end

def check_and_tag_punctuation(punct, tag_set)
  if punct.empty?
    'O'
  elsif punct == ',' || punct == ';' || punct == ':' || punct == '!, ' || punct == '"' || punct == "'"
    tag_set[punct]
  else
    'O'
  end
end

