```javascript
const attributesToIgnore = ['value', 'checked', 'selected'];

/**
 * Determine if a property is a reactive property based on its type.
 * @param {object} propsComponent Props object for the Vue component
 * @param {string} propName Property name to check
 * @returns {boolean}
 */
function isReactive(propsComponent, propName) {
  const descriptor = Object.getOwnPropertyDescriptor(propsComponent, propName);
  return (
    descriptor && typeof descriptor.get === 'function' && descriptor.set !== undefined
  );
}

/**
 * Validate method modifies internal component state
 * @param {AstNode} node Method node to check
 * @param {RuleContext} context The ESLint rule context
 * @returns {IterableIterable<Error>[]}
 */
function validateMethodModifiesState(node, context) {
  // Ignore events and lifecycle hook methods that don't modify internal state
  const ignoredNodeTypes = ['MemberExpression', 'CallExpression'];
  const ignorePath = context.getImplicits().findPath(node, (path) => {
    if (path.isEventDecorator() || path.isLifecycleHook()) {
      return true;
    }
    if (ignoredNodeTypes.includes(path.node.type)) {
      const parent = path.parent;
      const propKeyword = parent.findParent((node) => node.type === 'ObjectPattern');
      if (propKeyword) {
        // Ignore if property does not modify internal state
        const prop = propKeyword.patterns[0];
        if (attributesToIgnore.includes(prop.key.name)) {
          return true;
        }
        if (isReactive(context.getAncestors().find((ancestor) => ancestor.type === 'ObjectExpression'), prop.key.name)) {
          return false;
        }
      }
    }
    return false;
  });
  if (ignorePath !== null) {
    return [];
  }

  // Find references to methods that modify internal state
  const references = context.getReferenceNodes(node);
  const modifyStateReferences = references.filter((reference) => {
    const identifier = reference.parent.argument.destructure()[0];
    if (reference.parent.type === 'MemberExpression') {
      return isReactive(context.getAncestors().find((ancestor) => ancestor.type === 'ObjectExpression'), identifier.name);
    }
    return true;
  });

  // Emit message if modifying state reference found
  if (modifyStateReferences.length > 0) {
    return [
      context.createRuleMessage('vue/no-modify-state-in-methods', {
        node: node,
      }),
    ];
  }
  return [];
}

module.exports = {
  create: function(context) {
    return {
      MemberExpression(path) {
        if (path.isEventName()) {
          return;
        }
        const node = path.node;
        if (
          [
            'beforeCreate',
            'created',
            'beforeMount',
            'mounted',
            'beforeUpdate',
            'updated',
            'activated',
            'deactivated',
            'beforeDestroy',
            'destroyed',
            'errorCaptured',
            'renderTracked',
            'renderTriggered',
          ].includes(node.property.name)
        ) {
          return validateMethodModifiesState(path.node, context);
        }
      },
    };
  },
  meta: {
    type: 'problem',
    fixable: 'code',
    docs: { description: 'Prevent modifying internal component state in methods' },
    messages: {
      'vue/no-modify-state-in-methods': 'Do not modify internal component state in {{name}}',
    },
    schema: [],
  },
};
```

Описание:

- Определения для `isReactive()` и `attributesToIgnore` являются вспомогательными функциями, которые используются для определения изменяющих свойства компопнетента методами жизненного цикла.
- `validateMethodModifiesState()` - основная функция, в которой проанализируется узел метода жизненного цикла, и будут найдены методы, которые изменяют внутреннее состояние компонента (на основе проверки на присутствие обращения к изменяемому реактивному свойству компонента).
- `create()` - функция, зарегистрированная в ESLint, которая использует валидацию `MemberExpression` в определенных именованных свойствах жизненного цикла, которые представляет собой методы жизненного цикла Vue.js компонента (`beforeCreate`, `created`, ...).
