function validateSingleResponsibility(node, context) {
  const methodContent = node.body.body.map((statement) => statement.type).join(',');
  const methodName = node.id.name;

  if (methodContent.includes('CallExpression')) {
    const callee = node.body.body.find((s) => s.type === 'ExpressionStatement').expression.callee;

    // Проверяем, если метод вызывает другие публичные методы
    if (callee.type === 'MemberExpression') {
      const publicMethod = context.getAncestor((node) => {
        return node.type === 'ObjectExpression' && node.parent.type === 'ExportNamedDeclaration' && node.parent.declaration?.property?.key?.name === methodName;
      });

      // Проверяем, являются ли вызываемые методы публичными для текущего компонента
      if (publicMethod?.property?.shorthand === false && publicMethod?.property?.value?.type === 'ArrayExpression') {
        const calledPublicMethods = publicMethod?.property?.value?.elements.map((e) => e.object?.property?.name);

        if (calledPublicMethods.some((methodName) => ['-method-'].includes(methodName))) {
          return [
            context.createRuleMessage('vue/single-responsibility-public-method', {
              node,
              methodName,
              calledPublicMethods: calledPublicMethods.join(', '),
            }),
          ];
        }
      }
    }
  }

  if (methodContent.includes('AssignmentExpression') && methodContent.includes('CallExpression')) {
    const assignmentType = node.body.body.find((s) => s.type === 'AssignmentExpression');
    const methodNameAssignment = assignmentType?.left?.object?.property?.name;

    // Проверяем, если метод присваивает значение, также вызывая публичный метод
    if (methodNameAssignment) {
      const publicMethod = context.getAncestor((node) => {
        return node.type === 'ObjectExpression' && node.parent.type === 'ExportNamedDeclaration' && node.parent.declaration?.property?.key?.name === methodName;
      });

      // Проверяем, являются ли вызываемые методы публичными для текущего компонента
      if (publicMethod?.property?.shorthand === false && publicMethod?.property?.value?.type === 'ArrayExpression') {
        const calledPublicMethods = publicMethod?.property?.value?.elements.map((e) => e.object?.property?.name);

        if (calledPublicMethods.some((methodName) => ['-method-'].includes(methodName))) {
          return [
            context.createRuleMessage('vue/single-responsibility-public-method', {
              node,
              methodName,
              calledPublicMethods: calledPublicMethods.join(', '),
            }),
          ];
        }
      }
    }
  }

  return [];
}

module.exports = {
  create: function(context) {
    return {
      ExportNamedDeclaration(path) {
        if (path.node.declaration?.kind === 'ObjectExpression') {
          const componentMethods = path.node.declaration?.properties.filter((prop) => prop.key.type === 'Identifier' && prop.kind === 'init');
          componentMethods.forEach((method) => {
            if (method.key.name[0] !== '_') { // игнорируем методы с префиксом "_"
              validateSingleResponsibility(method.value, context);
            }
          });
        }
      },
    };
  },
  meta: {
    type: 'problem',
    fixable: 'code',
    docs: { description: 'Ensure public method\'s single responsibility' },
    messages: {
      'vue/single-responsibility-public-method': 'Public method {{methodName}} has multiple responsibilities, calls {{calledPublicMethods}}',
    },
    schema: [],
  },
};
```

Описание:

- `validateSingleResponsibility()` - основная функция, в которой проанализируется публичный метод Vue.js компонента, и будут найдены методы с нарушением принципа единственной ответственности, вызывающие другие публичные методы.
- `create()` - функция, зарегистрированная в ESLint, которая проанализирует публичные методы Vue.js компонентов (`ExportNamedDeclaration`) и вызовы публичных методов (`CallExpression`) в соответствующих блок кода.
- `meta` содержит настройки, связанные с правилом ESLint, среди которых описание, сообщения пользователю и настройки схемы (не используются в данном случае).

