Вот пример настроек для ваших компонентов Vue.js, которые будут проверяться на наличие методов, изменяющих внутреннее состояние и вызывающих друг друга:

```vue
<template>
  <div>
    <h1>{{ title }}</h1>
    <ul>
      <li v-for="item in items" :key="item.id">{{ item.name }}</li>
    </ul>
    <button @click="addItem">Добавить</button>
    <button @click="removeAllItems">Удалить все</button>
  </div>
</template>

<script>
export default {
  data() {
    return {
      title: 'Мои Items',
      items: [],
    };
  },
  methods: {
    addItem() {
      this.items.push({ id: Date.now(), name: `NewItem ${this.items.length}` });
    },
    removeAllItems() {
      this.items = [];
    },
    // Пример метода, измениющего состояние компонента и вызывающего из списка методов
    editItem(item) {
      const index = this.items.findIndex(({ id }) => id === item.id);
      this.items[index] = { ...item, name: `Edited Item ${this.items[index].name}`};
      this.changeFilter('edited');
    },
    changeFilter(filter) {
      // ...
    },
  },
  beforeUpdate() {
    // Вызов editItem из beforeUpdate, который изменяет state и вызывает changeFilter
    this.editItem(this.items.find(({ completed }) => !completed));
  },
};
</script>
```

В примере, с информацией о компоненте выше, расположенный в области методов `addItem`, `removeAllItems` и `changeFilter` не изменят внутреннее состояние компонента, поэтому на них не будет срабатывать правило проверки.

В то же время вызов метода `editItem`, который изменяет внутреннее состояние компонента (`items`) и вызывает ещё один метод, изменяющий некие другие данные (`changeFilter`), приведёт к ошибке при проверки с новым пользовательским правилом ESLint.

Ниже приведен пользовательское правило ESLint для Vue.js, которое проверяет, содержат ли обновленные хук-лифцикм методы операции, изменяющие внутреннее состояние компонента. Дополнительно, оно проверяет, вызывают ли эти методы другие методы, изменяющие состояние компонента.

Правило именуется `vue/update-hook-modifiers-state`, и в таблице конфигурации его можно завести так:

```json
{
  "rules": {
    "vue/update-hook-modifiers-state": ["error", {
        // Настройки правила (описаны ниже)
    }]
  }
}
```

Правило нацелено на триггеровы методы следующих жизненных циклов компонента Vue: `beforeUpdate`, `updated`, `beforeDestroy`, `destroyed`.

Реализация:

1. Создадим новый файл под названием `vue-update-hook-modifiers-state.js` в каталоге локализированных настроек ESLint (`/path/to/project/.eslintrc.json`) и напишем следующий код:

```javascript
const modifiersState = {
  CHANGE_STATE_METHOD: 'changeStateMethod',
  CALLS_CHANGE_STATE_METHOD: 'callsChangeStateMethod'
};

module.exports = {
  meta: {
    type: 'problem',
    fixable: 'code',
    messages: {
      [modifiersState.CHANGE_STATE_METHOD]: 'Метод {{methodName}} изменяет внутреннее состояние компонента {{componentName}}.',
      [modifiersState.CALLS_CHANGE_STATE_METHOD]: {
        code: modifiersState.CALLS_CHANGE_STATE_METHOD,
        description: 'Метод {{methodName}} вызывает другой метод, изменяющий внутреннее состояние компонента {{componentName}}',
        fixes: ({ code, Fix }) => [
          new Fix({
            range: [],
            text: `${code}:\n  return () => {\n    ${code};\n  };`
          })
        ]
      }
    },
    docs: {
      description: 'Проверяет, содержат ли обновленные хук\-лифцикм методы операций, изменяющие внутреннее состояние компонента Vue.js, и сообщает о любых вызовах других таких методов.'
    },
    schema: [
      {
        type: 'object',
        properties: {
          ignoreMethods: {
            type: 'array',
            items: { type: 'string' },
            default: []
          }
        },
        additionalProperties: false
      }
    ]
  },

  create: function(context) {
    const ignoreMethods = context.options[0]?.ignoreMethods || [];

    return {
      'FunctionalComponent:opening'() {},
      'Component:opening'(node) {
        context.registerMethod('check-hooks', {
          declare: true,
          sponsor: true,
          executor: handleHooks
        });
      }
    };

    function handleHooks(node) {
      const { methods } = node;
      if (!methods) return;

      const { hooks } = methods;
      if (!hooks) return;

      const { beforeUpdate, updated, beforeDestroy, destroyed } = hooks;

      if (beforeUpdate) {
        beforeUpdate.forEach(checkMethod);
      }
      if (updated) {
        updated.forEach(checkMethod);
      }
      if (beforeDestroy) {
        beforeDestroy.forEach(checkMethod);
      }
      if (destroyed) {
        destroyed.forEach(checkMethod);
      }

      function checkMethod(method) {
        if (ignoreMethods.includes(method.key.name)) {
          return;
        }
        if (method.value.body.type !== 'BlockStatement') {
          return context.report({
            node,
            message: modifiersState.CHANGE_STATE_METHOD,
            data: {
              methodName: method.key.name,
              componentName: getComponentName(context)
            }
          });
        }

        const stateChangeExpressions =
          method.value.body.body.filter(isStateChangeExpression);

        if (stateChangeExpressions.length > 0) {
          context.report({
            node,
            message: modifiersState.CHANGE_STATE_METHOD,
            data: {
              methodName: method.key.name,
              componentName: getComponentName(context)
            }
          });

          const callsChangeStateExpressions =
            stateChangeExpressions.filter(isCallsChangeStateExpression);

          if (callsChangeStateExpressions.length > 0) {
            context.report({
              node,
              message: modifiersState.CALLS_CHANGE_STATE_METHOD,
              data: {
                methodName: method.key.name,
                componentName: getComponentName(context)
              },
              fix: (fixer) =>
                fixer.insertAfter(
                  method.value.body.body[callsChangeStateExpressions[0].start""",
                  modifiersState.CALLS_CHANGE_STATE_METHOD
                    .replace('{{methodName}}', method.key.name)
                    .replace('{{componentName}}', getComponentName(context))
                ) + '\n'
              + fixer.replaceTextRange(
                  [stateChangeExpressions[0].start, stateChangeExpressions[0].end],
                  `${modifiersState.CALLS_CHANGE_STATE_METHOD}:\n  return () => {\n    ${getWrappedExpression(
                    stateChangeExpressions[0]
                  )};\n  };\n`
                )
            });
          }
        }
      }

      function isStateChangeExpression(node) {
        return (
          node.type === 'ExpressionStatement' &&
          node.expression.type === 'AssignmentExpression' &&
          node.expression.left.type === 'MemberExpression' &&
          node.expression.left.object.type === 'ThisExpression' &&
          node.expression.right.type === 'ObjectExpression' &&
          node.expression.right.properties.some((prop) =>
            prop.type === 'Property' && prop.key.type === 'Identifier' && prop.value.type === 'Literal'
          )
        );
      }

      function isCallsChangeStateExpression(node) {
        return (
          node.type === 'ConditionalExpression' &&
          node.test.type === 'Identifier' &&
          node.test.name === 'this' &&
          node.alternate.type === 'SpreadElement' &&
          node.alternate.argument.type === 'ObjectExpression' &&
          node.alternate.argument.properties.some((prop) =>
            prop.type === 'Property' && prop.key.type === 'Identifier' && prop.value.type === 'Literal'
          )
        );
      }

      function getWrappedExpression(expression) {
        const wrappedExpr = expression.expression.right;

        // Обернем выражение в функцию,
        // чтобы ESLint мог исправить вызовы в асинхронных методах
        const wrappedExprStr = `() => ${getErrorMessage(
          context,
          wrappedExpr
        )}`;

        return wrappedExprStr;
      }

      function getErrorMessage(context, expr) {
        const { sourceCode } = context;

        try {
          sourceCode.unparse(expr);
        } catch (error) {
          return error.message;
        }

        return String(expr);
      }

      function getComponentName(context) {
        // Здесь необходимо определить наименование компонента,
        // соствующее из имени файла и именревйщика
        const { filename, options: { parserOptions } } = context;

        const fileName = parserOptions.sourceType === 'module'
          ? parserOptions.parser.filename.replace(/\.vue$/, '')
          : filename.replace(/\.vue$/, '');
        const componentName = parserOptions.parser.__COMPILER_OPTIONS?.filename
          .replace(/\.vue$/, '').split('/').pop();

        return `${componentName} (в файле ${fileName})`;
      }
    }
  }
};
```

2. Скопируйте и вставьте приведенный выше код в созданный файл.

